package bd.hscsolution.admin;
import bd.hscsolution.security.*; import jakarta.validation.Valid; import jakarta.validation.constraints.NotEmpty; import java.util.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import org.springframework.jdbc.core.JdbcTemplate;
@RestController @RequestMapping("/api/v1/admin/users") public class AdminUserController{
 private final JdbcTemplate db; private final AuditService audit; public AdminUserController(JdbcTemplate db,AuditService audit){this.db=db;this.audit=audit;}
 @PutMapping("/{userId}/roles") @PreAuthorize("hasAuthority('PERM_ROLE_MANAGE')") public Map<String,Object> setRoles(@PathVariable UUID userId,@Valid @RequestBody RoleRequest req,@AuthenticationPrincipal AuthPrincipal actor){List<UUID> ids=new ArrayList<>();for(String code:req.roles()){UUID id=db.query("select id from role where code=?",rs->{if(!rs.next())return null;return rs.getObject(1,UUID.class);},code);if(id==null)throw new IllegalArgumentException("Unknown role code: "+code);ids.add(id);}db.update("delete from user_role where user_id=?",userId);for(UUID id:ids)db.update("insert into user_role(user_id,role_id) values(?,?)",userId,id);audit.record(UUID.fromString(actor.userId()),"ROLE_CHANGE","APP_USER",userId,Map.of(),Map.of("roles",req.roles()));return Map.of("userId",userId,"roles",req.roles());}
 @PostMapping("/{userId}/devices/{deviceId}/reset") @PreAuthorize("hasAuthority('PERM_DEVICE_RESET')") public Map<String,Object> resetDevice(@PathVariable UUID userId,@PathVariable UUID deviceId,@AuthenticationPrincipal AuthPrincipal actor){int n=db.update("update device set status='REVOKED' where id=? and user_id=?",deviceId,userId);if(n==0)throw new IllegalArgumentException("Device not found");db.update("update refresh_token set revoked_at=coalesce(revoked_at,now()) where device_id=?",deviceId);audit.record(UUID.fromString(actor.userId()),"DEVICE_RESET","DEVICE",deviceId,Map.of("userId",userId.toString()),Map.of("status","REVOKED"));return Map.of("deviceId",deviceId,"status","REVOKED");}
 public record RoleRequest(@NotEmpty List<String> roles){}
}
